css='''body{margin:0;background:#f5f1e9;color:#292b2a;font:17px/1.65 system-ui}main,header,footer{max-width:850px;margin:auto;padding:22px}h1,h2,h3{font-family:Georgia,serif;line-height:1.2}h1{font-size:clamp(32px,6vw,52px)}a{color:#325550}section,article{border:1px solid #cdc9c0;background:#fffdf8;border-radius:12px;padding:22px;margin:18px 0}input,select,textarea,button{font:inherit;box-sizing:border-box;max-width:100%}input,textarea,select{width:100%;padding:10px;border:1px solid #797e77;border-radius:6px;background:#fff;color:#242824}label{display:block;margin:12px 0}button,.button{display:inline-block;padding:10px 16px;background:#325550;color:white;border:0;border-radius:6px;cursor:pointer;margin:6px 4px 6px 0}button:focus-visible,a:focus-visible{outline:3px solid #a75428;outline-offset:3px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#ede9e1;padding:14px;font:15px/1.6 system-ui}img{width:100%;height:auto;border-radius:8px}nav{display:flex;gap:18px;flex-wrap:wrap}.muted{color:#535952}table{width:100%;border-collapse:collapse;font-size:15px}th,td{text-align:left;padding:8px;border-bottom:1px solid #ccc}*{box-sizing:border-box}output{font-weight:700} .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px} @media(max-width:500px){main,header,footer{padding:16px}section,article{padding:16px}}'''
def page(name,title,body,script=''):
 (R/name).write_text(f'<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} · Redes Sociais v6.2</title><style>{css}</style></head><body><header><nav><a href="curso.html#trilha">Curso</a><a href="caderno.html">Fichas</a><a href="hooks.html">33 aberturas</a><a href="planner.html">Planejador</a></nav></header><main><p>INEMA.CLUB · Redes Sociais v6.2</p><h1>{E(title)}</h1>{body}</main><footer><a href="https://inema.club">Voltar ao portal INEMA.CLUB</a></footer><script>{script}</script></body></html>')
groups=[
('Resultado primeiro',[('Uma ideia para reunir os lápis da mesa.','Mostrar os lápis reunidos e explicar o recipiente.'),('Veja onde guardei este cartão.','Revelar o cartão num envelope compatível.'),('Este pequeno espaço pode receber os papéis soltos.','Mostrar uma bandeja e seus limites de tamanho.')]),
('Pergunta cotidiana',[('Seus lápis também ficam espalhados?','Responder com uma organização concreta.'),('Onde vai o cartão depois de ler a mensagem?','Mostrar uma opção de guarda.'),('Qual papel você precisa encontrar primeiro?','Separar papéis por uma necessidade definida.')]),
('Detalhe que importa',[('Antes de usar o pote, confira esta borda.','Mostrar a inspeção de integridade, sem alegar segurança de um objeto gerado.'),('Esta dobra muda o espaço do envelope.','Explicar a dobra no exemplo apresentado.'),('O tamanho da base faz diferença nesta bandeja.','Comparar apoio e espaço de uma proposta concreta.')]),
('Comparação honesta',[('Duas formas de apresentar o mesmo pote.','Mostrar enquadramentos e dizer o que muda.'),('Envelope aberto ou fechado: o que você precisa mostrar?','Comparar função de cada imagem.'),('Mais espaço vazio ou mais objetos nesta foto?','Explicar a escolha visual sem prometer alcance.')]),
('Bastidor',[('Foi assim que escolhi o primeiro plano.','Mostrar a decisão e sua razão.'),('Esta imagem foi criada com IA; veja o que revisei.','Identificar origem e critérios realmente conferidos.'),('A primeira frase mudou depois desta leitura.','Mostrar as duas versões próprias.')]),
('Limite útil',[('Um pote ajuda aqui, mas não resolve tudo.','Mostrar o uso e uma limitação concreta.'),('Este envelope é uma ideia para um cartão pequeno.','Delimitar o exemplo, sem prometer capacidade universal.'),('Uma bandeja de papel pede cuidado com o uso.','Explicar limites de material e não inventar teste.')]),
('Passo específico',[('Comece escolhendo quais lápis ficam na mesa.','Mostrar um critério de seleção.'),('Separe o cartão antes de planejar o envelope.','Explicar como o conteúdo orienta o tamanho.'),('Defina o lugar da bandeja antes de ocupar a mesa.','Mostrar planejamento de espaço.')]),
('Curiosidade respondida',[('O que cabe neste envelope?','Revelar o cartão específico e o limite do exemplo.'),('Por que deixei este espaço livre na foto?','Explicar área de leitura ou respiro.'),('Qual destas aberturas mostra melhor a ideia?','Comparar clareza sem fingir teste com audiência.')]),
('Uma mudança',[('Mudei só o enquadramento; compare a leitura.','Mostrar antes e depois com condições identificadas.'),('Retirei uma frase para a explicação respirar.','Apresentar as versões de roteiro.'),('Troquei o fundo, mantendo o objeto.','Mostrar a comparação e reconhecer alterações involuntárias.')]),
('Convite à observação',[('Olhe onde seus materiais mais se acumulam.','Propor observar a própria mesa, sem coletar fotos pessoais.'),('Repare no que fica escondido dentro do envelope.','Mostrar abertura suficiente para compreender o conteúdo.'),('Veja se consegue ler esta frase no celular.','Demonstrar tamanho e tempo de leitura.')]),
('Retomada',[('A ideia do pote deixou uma pergunta importante.','Responder uma pergunta real ou identificá-la como pergunta do roteiro.'),('Hoje mostro o limite que faltou explicar.','Acrescentar um cuidado verdadeiro à ideia anterior.'),('O próximo teste muda apenas a abertura.','Apresentar hipótese e o que será mantido.')])]
body='<p>33 exemplos originais em português. São possibilidades de escrita, sem comprovação de alcance. Adapte a frase e produza a entrega correspondente. Não alegue ter feito algo que ainda não fez.</p>'
records=[];n=0
for group,rows in groups:
 body+=f'<section><h2>{E(group)}</h2>'
 for hook,payoff in rows:
  n+=1;records.append(dict(numero=n,grupo=group,abertura=hook,entrega=payoff));body+=f'<article><h3>{n:02d}. {E(hook)}</h3><p><b>O que entregar:</b> {E(payoff)}</p></article>'
 body+='</section>'
