(R/'context/aberturas.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n')
lessons=json.loads((R/'context/aulas-editoriais.json').read_text())
body='''<p>Fichas autorais do caso fictício Reuso de Bolso. Copie para suas notas. Nenhum dado abaixo veio de uma campanha real.</p>
<section id="comparacao"><h2>Compare total e taxa</h2><p><b>Exemplo fictício:</b> mesma plataforma, mesmo indicador e 48 horas desde cada publicação.</p><table><thead><tr><th>Versão</th><th>Visualizações</th><th>Compart.</th><th>Taxa</th></tr></thead><tbody><tr><td>A</td><td>1.000</td><td>20</td><td>2%</td></tr><tr><td>B</td><td>500</td><td>15</td><td>3%</td></tr></tbody></table><p>Taxa = compartilhamentos ÷ visualizações × 100. B tem maior taxa; A tem mais ações totais. Isso não isola uma causa nem prevê vendas.</p><div class="grid"><label>Visualizações<input id="base" type="number" min="0" step="1" value="1000"></label><label>Compartilhamentos<input id="acoes" type="number" min="0" step="1" value="20"></label></div><p>Razão calculada: <output id="taxa" aria-live="polite">2%</output></p><p class="muted">Contagens inteiras não negativas. Base zero ou ausente não produz uma taxa. Esta razão não é percentual de pessoas únicas e pode superar 100% se houver ações repetidas.</p></section>
<section><h2>Pesquisa em quatro camadas</h2><pre>Endereço e autor:
Data da consulta e duração:
Pergunta respondida:
Imagem — observação e tempo:
Texto/fala — observação e tempo:
Som — observação e tempo:
Estrutura — abertura, promessa, demonstração e convite:
O que observei:
Minha hipótese:
O que vou criar com execução própria:</pre></section>
<section><h2>Roteiro ilustrado · exemplo autoral de 20 segundos</h2><p>A duração é uma proposta. Leia sua voz em voz alta e ajuste a montagem. Imagens geradas não provam execução física.</p><ol><li><b>0–3s:</b> lápis espalhados. Fala: Uma ideia para reunir seus lápis.</li><li><b>3–15s:</b> pote com lápis. Fala: Escolha um recipiente íntegro e estável. Separe o que usa e planeje onde deixar.</li><li><b>15–20s:</b> organização ilustrada. Fala: Confira a borda antes de usar. Guarde esta ideia.</li></ol><p>Identificação: exemplo ilustrado com IA. Se filmar uma execução real, descreva apenas o que você realmente fez. Música é opcional.</p></section>
<section><h2>Revisão antes de publicar</h2><pre>Arquivo e versão:
[ ] Entendi o assunto.
[ ] Li o texto sem pausar.
[ ] Ouvi a fala inteira.
[ ] Vi o objeto e seus detalhes necessários.
[ ] Reconheci a identificação de IA quando aplicável.
Direitos e créditos conferidos:
Legenda e capa conferidas:
Controle de IA da rede conferido:
Visibilidade escolhida:
Situação: pendente / corrigir / aprovado
Publicação verificada — endereço e data:</pre></section>'''
for i,d in enumerate(lessons,1):body+=f'<section id="aula-{i}"><h2>Aula {i} · {E(d["titulo"])}</h2><pre>{E(d["molde"])}</pre></section>'
script="""function calc(){const b=document.querySelector('#base').value,a=document.querySelector('#acoes').value;let r='Não disponível';if(b!==''&&a!==''&&Number.isInteger(+b)&&Number.isInteger(+a)&&+b>0&&+a>=0)r=(+a/+b*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%';document.querySelector('#taxa').textContent=r;}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',calc));calc();"""
page('caderno.html','Fichas para produzir e observar',body,script)
body='''<p>Planeje sete dias de trabalho, incluindo produção e observação. Este calendário não publica nem agenda posts nas redes. Salva apenas neste navegador; exporte uma cópia para preservar seu trabalho.</p><p id="status" role="status">Pronto para preencher.</p><label>Projeto<input id="projeto" maxlength="200" value="Meu projeto"></label><label>Três pilares e ideias<textarea id="pilares" rows="4" maxlength="5000" placeholder="Uma categoria e duas ideias por linha"></textarea></label><div id="dias"></div><button id="exportar" type="button">Exportar cópia JSON</button><label>Importar cópia JSON<input id="importar" type="file" accept="application/json,.json"></label><p>Importar substitui os campos atuais pela cópia escolhida. Exporte antes para preservar outra versão. Não guarde senhas ou dados pessoais aqui.</p>'''
script=r'''
const KEY='inema-redes-v62-planner';const defaults=['Pesquisar referências','Escrever roteiro','Produzir imagens e voz','Montar e revisar','Publicar vídeo conferido','Preparar observação','Consultar dados no intervalo previsto'];const statuses=['planejado','em produção','publicado','concluído'];let state={version:1,projeto:'Meu projeto',pilares:'',dias:defaults.map(t=>({data:'',tarefa:t,situacao:'planejado',evidencia:''}))};const msg=t=>document.querySelector('#status').textContent=t;
function valid(s){return s&&s.version===1&&typeof s.projeto==='string'&&s.projeto.length<=200&&typeof s.pilares==='string'&&s.pilares.length<=5000&&Array.isArray(s.dias)&&s.dias.length===7&&s.dias.every(d=>d&&typeof d.data==='string'&&(/^(\d{4}-\d{2}-\d{2})?$/.test(d.data))&&typeof d.tarefa==='string'&&d.tarefa.length<=1000&&statuses.includes(d.situacao)&&typeof d.evidencia==='string'&&d.evidencia.length<=3000);}
try{const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(valid(s))state=s;else msg('A cópia local é inválida. Exporte seus próximos registros para preservar o trabalho.');}}catch(e){msg('Não foi possível ler o armazenamento local. Use a exportação.');}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));msg('Salvo neste navegador.');}catch(e){msg('Não foi possível salvar neste navegador. Exporte uma cópia agora.');}}
function field(label,tag,value,fn,attrs={}){const l=document.createElement('label');l.append(document.createTextNode(label));const el=document.createElement(tag);Object.assign(el,attrs);el.value=value;el.addEventListener('input',()=>{fn(el.value);save();});l.append(el);return l;}
function render(){document.querySelector('#projeto').value=state.projeto;document.querySelector('#pilares').value=state.pilares;const root=document.querySelector('#dias');root.replaceChildren();state.dias.forEach((d,i)=>{const s=document.createElement('section');const h=document.createElement('h2');h.textContent='Dia '+(i+1);s.append(h,field('Data','input',d.data,v=>d.data=v,{type:'date'}),field('Tarefa','textarea',d.tarefa,v=>d.tarefa=v,{rows:2,maxLength:1000}));const l=document.createElement('label');l.textContent='Situação';const select=document.createElement('select');statuses.forEach(v=>{const op=document.createElement('option');op.value=v;op.textContent=v;select.append(op);});select.value=d.situacao;select.addEventListener('change',()=>{d.situacao=select.value;save();});l.append(select);s.append(l,field('Evidência, endereço ou pendência','textarea',d.evidencia,v=>d.evidencia=v,{rows:3,maxLength:3000}));root.append(s);});}
render();document.querySelector('#projeto').addEventListener('input',e=>{state.projeto=e.target.value;save();});document.querySelector('#pilares').addEventListener('input',e=>{state.pilares=e.target.value;save();});document.querySelector('#exportar').addEventListener('click',()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='planejamento-redes-v62.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);msg('Cópia exportada. Confira o arquivo na pasta de arquivos recebidos.');});document.querySelector('#importar').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error();const s=JSON.parse(await f.text());if(!valid(s))throw Error();state={version:1,projeto:s.projeto,pilares:s.pilares,dias:s.dias.map(d=>({data:d.data,tarefa:d.tarefa,situacao:d.situacao,evidencia:d.evidencia}))};render();save();msg('Cópia importada e salva neste navegador.');}catch(err){msg('Arquivo inválido. Seus campos atuais foram preservados.');}e.target.value='';});
'''
page('planner.html','Uma semana possível',body,script)
# Two authored instructional visuals, with real numerical and temporal relationships.
extras={
'5':'<figure class="largo"><div class="janela"><div class="janela-body"><p><b>Dados fictícios · mesmo indicador e intervalo</b></p><p>A: 20 compartilhamentos ÷ 1.000 visualizações = <b>2%</b></p><p>B: 15 compartilhamentos ÷ 500 visualizações = <b>3%</b></p><p>B tem maior taxa. A tem mais ações totais. Isso não prova a causa.</p></div></div><figcaption>Quadro autoral: contagens e denominadores explícitos. Nenhuma campanha real foi medida.</figcaption></figure>',
'17':'<figure class="largo"><div class="janela"><div class="janela-body"><p><b>Roteiro ilustrado de 20 segundos</b></p><p>0–3s · abertura: lápis espalhados.</p><p>3–15s · explicação: recipiente e organização.</p><p>15–20s · cuidado e convite para guardar a ideia.</p></div></div><figcaption>Plano de tempo autoral. Leia a voz e ajuste a montagem; não é um vídeo já produzido.</figcaption></figure>'}
(R/'context/visuais-extras.json').write_text(json.dumps(extras,ensure_ascii=False,indent=2)+'\n')
